// What a traveller leaving at 07:00 has within reach by each minute, in each of
// the two runs compared (SIDES, coloured as everywhere on the tab), up to the
// cutoff: people, area, transit stops and parks, four small charts that keep
// the whole curve. The dashed line is
// the end of the Time Brush window (${t1}), the minute the figures above are
// read at; with no window it is the cutoff. Nothing to click.
//
// @constants begin
const SIDES = [{"key": "A", "name": "From A", "color": "#5794F2"}, {"key": "B", "name": "From B", "color": "#FF9830"}];
const MEASURES = [
  { key: 'people', title: 'People', decimals: 0 },
  { key: 'km2', title: 'Area, km²', decimals: 1 },
  { key: 'stops', title: 'Transit stops', decimals: 0 },
  { key: 'parks', title: 'Parks', decimals: 0 },
];
const WINDOW_END = '${t1}';
const SERVICE_DAY = '${date}';
const DEPARTURE = 'T07:00:00Z';
// @constants end

const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const weak = theme.colors.border.weak;
const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const sides = col('side');
const minutes = col('minute').map(Number);

const end = Date.parse(context.grafana.replaceVariables(WINDOW_END));
const start = Date.parse(context.grafana.replaceVariables(SERVICE_DAY) + DEPARTURE);
const last = minutes.length ? Math.max(...minutes) : 0;
const at = Number.isFinite(end) && Number.isFinite(start) ? Math.min(last, Math.round((end - start) / 60000)) : last;

const fmt = (v, d) => (v == null ? '–' : Number(v).toLocaleString('en', { maximumFractionDigits: d }));
const boxes = [
  { left: '1%', top: 26, width: '44%', height: '30%' },
  { left: '53%', top: 26, width: '44%', height: '30%' },
  { left: '1%', top: '58%', width: '44%', height: '30%' },
  { left: '53%', top: '58%', width: '44%', height: '30%' },
];

const grid = [];
const xAxis = [];
const yAxis = [];
const title = [];
const series = [];
MEASURES.forEach((m, i) => {
  const values = col(m.key).map((v) => (v == null ? null : Number(v)));
  grid.push({ ...boxes[i], containLabel: true });
  title.push({
    text: m.title,
    left: boxes[i].left,
    top: i < 2 ? 0 : `${parseFloat(boxes[i].top) - 6}%`,
    textStyle: { color: muted, fontSize: 12, fontWeight: 'normal' },
  });
  xAxis.push({
    gridIndex: i, type: 'value', min: 0, max: last, interval: last > 30 ? 15 : 5,
    axisLabel: { color: muted, formatter: (v) => `${v} min` },
    axisLine: { lineStyle: { color: weak } }, splitLine: { show: false },
  });
  yAxis.push({
    gridIndex: i, type: 'value',
    axisLabel: { color: muted, formatter: (v) => (v >= 1000 ? `${Math.round(v / 1000)}k` : v) },
    splitLine: { lineStyle: { color: weak } },
  });
  SIDES.forEach((o, j) => {
    const data = minutes.map((x, k) => (sides[k] === o.key ? [x, values[k]] : null)).filter(Boolean);
    series.push({
      name: o.name, type: 'line', xAxisIndex: i, yAxisIndex: i, data, showSymbol: false,
      lineStyle: { width: 2, color: o.color }, itemStyle: { color: o.color },
      areaStyle: j === 0 ? { color: o.color, opacity: 0.12 } : undefined,
      markLine: j === 0 ? {
        symbol: 'none', silent: true, label: { show: false },
        lineStyle: { color: muted, type: 'dashed' }, data: [{ xAxis: at }],
      } : undefined,
    });
  });
});

return {
  animation: false,
  backgroundColor: 'transparent',
  title,
  grid,
  xAxis,
  yAxis,
  series,
  tooltip: {
    trigger: 'axis',
    formatter: (items) => {
      const m = MEASURES[(items[0]?.seriesIndex ?? 0) >> 1];
      const head = `${m.title} within ${items[0]?.value?.[0]} min`;
      return [head, ...items.map((p) => `${p.marker} ${p.seriesName}: ${fmt(p.value?.[1], m.decimals)}`)].join('<br/>');
    },
  },
};

