options.afterRender:
// How each trip is made, as a form: one row per scenario, with the street
// network, walking or biking, the transit that counts and, with transit, how
// long the walk or ride to and from it may be and how many rides. Nothing is
// asked of R5 until Apply, which writes every variable at once: five changes
// cost one computation, not five. Without transit the trip is door to door by
// bike or on foot and only the cutoff limits it, so the two transit settings
// are greyed out. The rows show the dashboard's variables, so a shared link
// opens with its own scenarios.
//
// The panel's content is <div class="rform"></div>; its query names every
// variable below, so the form is drawn again when one changes elsewhere.
// @constants begin
const ROWS = [{"prefix": "", "badge": "A·B", "title": "Both markers", "color": "#C7D0D9"}];
const FIELDS = [
  { name: 'street', label: 'On the street', options: [['apie', 'Walk'], ['bici', 'Bike']] },
  { name: 'transit', label: 'Transit', checks: [['BUS', 'Bus'], ['TRAM', 'Tram']], none: 'none' },
  { name: 'walk', label: 'To/from transit', transitOnly: true, options: [['10', '10 min'], ['20', '20 min'], ['30', '30 min']] },
  { name: 'rides', label: 'Rides', transitOnly: true, options: [['1', '1'], ['2', '2'], ['4', 'up to 4']] },
  { name: 'network', label: 'Streets', options: [['base', 'Flat'], ['pendiente', 'With slope']] },
];
// @constants end

const box = context.element.querySelector('.rform');
if (!box) {
  return;
}
const read = (variable, multi) => {
  const raw = context.grafana.replaceVariables(multi ? '${' + variable + ':csv}' : '${' + variable + '}');
  return multi ? raw.split(',').filter((v) => v && v !== 'none') : raw;
};
const add = (parent, tag, cls, text) => {
  const el = document.createElement(tag);
  if (cls) {
    el.className = cls;
  }
  if (text !== undefined) {
    el.textContent = text;
  }
  parent.appendChild(el);
  return el;
};

// What the form holds, per row, and what the dashboard holds: Apply lights up
// when they differ.
const state = ROWS.map((row) => Object.fromEntries(FIELDS.map((f) => [f.name, read(row.prefix + f.name, Boolean(f.checks))])));
const saved = JSON.stringify(state);
box.replaceChildren();
const rows = add(box, 'div', 'rform-rows');
const apply = document.createElement('button');
const refresh = () => {
  rows.querySelectorAll('[data-transit-only]').forEach((el) => {
    const r = Number(el.dataset.row);
    el.disabled = state[r].transit.length === 0;
  });
  rows.querySelectorAll('.rform-hint').forEach((el) => {
    el.style.display = state[Number(el.dataset.row)].transit.length === 0 ? '' : 'none';
  });
  apply.disabled = JSON.stringify(state) === saved;
};

ROWS.forEach((row, r) => {
  const line = add(rows, 'div', 'rform-row');
  const badge = add(line, 'span', 'rform-badge', row.badge);
  badge.style.background = row.color;
  add(line, 'b', 'rform-title', row.title);
  for (const f of FIELDS) {
    const field = add(line, 'label', 'rform-field');
    add(field, 'span', 'rform-label', f.label);
    if (f.checks) {
      const group = add(field, 'span', 'rform-checks');
      for (const [value, text] of f.checks) {
        const item = add(group, 'label', 'rform-check');
        const input = add(item, 'input');
        input.type = 'checkbox';
        input.checked = state[r][f.name].includes(value);
        input.onchange = () => {
          const on = new Set(state[r][f.name]);
          if (input.checked) {
            on.add(value);
          } else {
            on.delete(value);
          }
          state[r][f.name] = f.checks.map(([v]) => v).filter((v) => on.has(v));
          refresh();
        };
        add(item, 'span', '', text);
      }
      const hint = add(field, 'span', 'rform-hint', 'door to door');
      hint.title = 'Without transit the trip is door to door: only the cutoff limits it.';
      hint.dataset.row = String(r);
    } else {
      const select = add(field, 'select');
      for (const [value, text] of f.options) {
        const option = add(select, 'option', '', text);
        option.value = value;
      }
      select.value = state[r][f.name];
      select.onchange = () => {
        state[r][f.name] = select.value;
        refresh();
      };
      if (f.transitOnly) {
        select.dataset.transitOnly = '1';
        select.dataset.row = String(r);
      }
    }
  }
});

apply.type = 'button';
apply.className = 'rform-apply';
apply.textContent = 'Apply';
apply.title = 'Write these settings to the dashboard: R5 computes the new travel times in about a second';
apply.onclick = () => {
  const update = {};
  ROWS.forEach((row, r) => {
    for (const f of FIELDS) {
      const value = state[r][f.name];
      update['var-' + row.prefix + f.name] = f.checks ? (value.length ? value : [f.none]) : value;
    }
  });
  context.grafana.locationService.partial(update, true);
};
box.appendChild(apply);
refresh();

