options.getOption:
// The places of each kind within reach in the Time Brush window, in each of the
// two runs compared (SIDES: the query's columns x and y), and how many minutes
// the nearest one takes, at the end of each bar. A kind with no bar is out of
// reach of that run in the window. Nothing to click.
//
// @constants begin
const SIDES = [{"col": "x", "name": "From A", "color": "#5794F2"}, {"col": "y", "name": "From B", "color": "#FF9830"}];
const KINDS = ["Transit stop", "Park", "Education", "Health", "Shopping"];
// @constants end

const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const weak = theme.colors.border.weak;
const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const kinds = col('kind');
const row = (kind, name) => {
  const i = kinds.indexOf(kind);
  const v = i < 0 ? null : col(name)[i];
  return v == null ? null : Number(v);
};

